// Works with Claude (bridge), Gemini and Ollama (local) responses
const res = $json;
if (res.stop_reason === 'max_tokens' || res.finishReason === 'MAX_TOKENS' || res.done_reason === 'length') throw new Error('Model hit its max output tokens.');

let text = Array.isArray(res.content)
  ? res.content.filter(b => b.type === 'text').map(b => b.text).join('')
  : (res.content?.parts || []).map(p => p.text || '').join('') || res.message?.content || res.text || '';
text = text.replace(/```(?:json)?/gi, '').trim();
const match = text.match(/\{[\s\S]*\}/);
if (!match) throw new Error('Model did not return JSON: ' + text.slice(0, 300));
const data = JSON.parse(match[0]);

// Escape LaTeX special characters in every string value
const map = {
  '\\': '\\textbackslash{}', '&': '\\&', '%': '\\%', '$': '\\$',
  '#': '\\#', '_': '\\_', '{': '\\{', '}': '\\}',
  '~': '\\textasciitilde{}', '^': '\\textasciicircum{}',
};
const esc = s => s.replace(/[\\&%$#_{}~^]/g, c => map[c]);
const walk = v =>
  typeof v === 'string' ? esc(v)
  : Array.isArray(v) ? v.map(walk)
  : v && typeof v === 'object'
    ? Object.fromEntries(Object.entries(v).map(([k, x]) => [k, walk(x)]))
    : v;

data.PROFILE_SUMMARY = data.PROFILE_SUMMARY || data.summary || data.basics?.summary || '';

// Plain-text keyword report shown on the web page
const matched = data.ATS_MATCHED || [], missing = data.ATS_MISSING || [], added = data.ATS_ADDED || [];
const report = [
  `ATS keywords covered: ${matched.length}/${matched.length + missing.length}`,
  missing.length ? `Not in your profile: ${missing.join(', ')}` : 'Every keyword of the offer is covered.',
  added.length ? `\nAdded beyond your profile (prepare to talk about these in interviews):\n- ${added.join('\n- ')}` : ''
].filter(Boolean).join('\n');

const out = walk(data);
out.ATS_REPORT = report;
return { json: out };

